window.MG_LAZY_DATA["data/lazy/resources/security-v26-035-86e41a516cfed50b.json"]={sha256:"86e41a516cfed50b7b48ecc1679127c9c4c09196fa6087af3e2b87e032359118",value:{"sources":[{"id":"v26-case-a4513a9c5c64d4da","url":"https://www.elastic.co/docs/reference/ecs","title":"Elastic Common Schema reference","titleEn":"Elastic Common Schema reference","publisher":"Elastic","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-035","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-035","related":[{"id":"security-v26-036","referenceUrls":["https://schema.ocsf.io/"],"title":"OCSF：跨產品事件語義與版本契約","titleEn":"OCSF: cross-product event semantics and version contracts","why":"用兩課的可觀察驗收條件比較模型邊界：350與900毫秒正確，原始與正規化時間都保留；缺時區及非法型別不被悄悄吞掉。 交付欄位映射表、四類時間測試與隔離事件範例。","whyEn":"Compare model boundaries using observable acceptance criteria: Recompute 350 and 900 ms, retain raw and normalized time and do not silently swallow missing zones or invalid types. Deliver field mappings, four time-test classes and quarantined-event examples.","difference":"選認證事件，將三個虛構產品的user、status、時間與來源映射到一份鎖定版本的schema；保留原始列與無法映射的欄位。","differenceEn":"Map authentication user, status, time and source from three fictional products into a pinned schema version; retain raw rows and unmapped fields.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["管線延遲=ingest_time−event_time，僅在兩端時鐘可比較時有意義；正規化不能把發生時間覆寫成收到時間。 同一時基下事件時間100000毫秒、索引時間100350毫秒；時間戳均已轉成整數毫秒。 100350−100000=350毫秒；索引時間改100900時延遲900毫秒。","語義完整率=所有必填且可解釋欄位通過的事件/總事件；JSON語法有效與schema有效、語義正確是三層不同判定。 合成240事件中，204筆通過必填欄位、型別與狀態語義驗證，36筆隔離。 204/240×100=85%；修正24筆後228/240×100=95%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Pipeline latency is ingest_time−event_time and requires comparable clocks; normalization must not overwrite occurrence time with arrival time. On one time basis, event time is 100000 ms and ingest time 100350 ms; both timestamps are normalized integer milliseconds. 100350−100000=350 ms; ingest time 100900 yields 900 ms.","Semantic completeness is events with all required interpretable fields divided by total events; valid JSON, valid schema and correct meaning are distinct checks. Of 240 synthetic events, 204 pass required-field, type and status-semantics checks, with 36 quarantined. 204/240×100=85%; correcting 24 yields 228/240×100=95%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-045","referenceUrls":["https://learn.microsoft.com/en-us/windows/security/identity-protection/credential-guard/"],"title":"Credential Guard：設定、執行狀態與相容性證據","titleEn":"Credential Guard: configured state, runtime and compatibility","why":"用兩課的可觀察驗收條件比較模型邊界：350與900毫秒正確，原始與正規化時間都保留；缺時區及非法型別不被悄悄吞掉。 交付欄位映射表、四類時間測試與隔離事件範例。","whyEn":"Compare model boundaries using observable acceptance criteria: Recompute 350 and 900 ms, retain raw and normalized time and do not silently swallow missing zones or invalid types. Deliver field mappings, four time-test classes and quarantined-event examples.","difference":"為40台虛構Windows工作站列硬體能力、政策設定、執行狀態與相容性案例；區分「已要求啟用」與「確認運作」。","differenceEn":"Inventory hardware capability, policy, runtime and compatibility for 40 fictional Windows workstations; distinguish requested enablement from verified operation.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["管線延遲=ingest_time−event_time，僅在兩端時鐘可比較時有意義；正規化不能把發生時間覆寫成收到時間。 同一時基下事件時間100000毫秒、索引時間100350毫秒；時間戳均已轉成整數毫秒。 100350−100000=350毫秒；索引時間改100900時延遲900毫秒。","可驗證覆蓋率=確認執行且通過相容性測試的裝置/範圍裝置；這是部署證據比例，不是可防止所有憑證攻擊的機率。 40台範圍裝置中34台有執行與相容性證據，6台仍待處理。 34/40×100=85%；補修4台後38/40×100=95%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Pipeline latency is ingest_time−event_time and requires comparable clocks; normalization must not overwrite occurrence time with arrival time. On one time basis, event time is 100000 ms and ingest time 100350 ms; both timestamps are normalized integer milliseconds. 100350−100000=350 ms; ingest time 100900 yields 900 ms.","Verified coverage is devices running the feature and passing compatibility tests divided by in-scope devices; this is deployment evidence, not universal credential-attack prevention probability. Of 40 in-scope devices, 34 have runtime and compatibility evidence and six remain pending. 34/40×100=85%; repairing four gives 38/40×100=95%.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-94d24d89e444f14b","url":"https://schema.ocsf.io/","title":"Open Cybersecurity Schema Framework","titleEn":"Open Cybersecurity Schema Framework","publisher":"OCSF","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-2d71d80dc2237864","url":"https://learn.microsoft.com/en-us/windows/security/identity-protection/credential-guard/","title":"Credential Guard overview","titleEn":"Credential Guard overview","publisher":"Microsoft","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
